// Create a new instance of the Viewer control and add it to the form.
Viewer reportViewer = new Viewer();
reportViewer.Dock = DockStyle.Fill;
this.Controls.Add(reportViewer);
// Load a report into the Viewer.
reportViewer.LoadDocument("path/to/your/report.rdlx");

// Instantiating the Viewer control and adding it to a form.
Viewer viewer = new Viewer();
viewer.Dock = DockStyle.Fill;
this.Controls.Add(viewer);
// Example of handling an error that might occur during document loading.
try
{
    viewer.LoadDocument("path/to/your/report.rdlx");
}
catch (Exception ex)
{
    viewer.HandleError(ex);
}

// Assuming 'viewer' is an instance of Viewer.
// Retrieving the list of shortcut commands available in the viewer.
var shortcutCommands = viewer.GetShortcutCommands();
foreach (var command in shortcutCommands)
{
    Console.WriteLine($"Command: {command.Command}, Enabled: {command.Enabled}");
}

// Assuming 'viewer' is an instance of Viewer.
// Enabling the Print command.
viewer.SetShortcutCommandState(ViewerCommand.Print, true);
// Disabling the ZoomIn command.
viewer.SetShortcutCommandState(ViewerCommand.ZoomIn, false);

protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
{
    if (keyData == (Keys.Control | Keys.F))
    {
        viewer.ShowFindDialog();
        return true;
    }
    return base.ProcessCmdKey(ref msg, keyData);
}

// Assuming 'viewer' is an instance of the Viewer class
// This will print to the default printer without showing the print dialog
bool printSuccess = viewer.Print(showPrintDialog: false);
if (printSuccess)
    MessageBox.Show("Printing initiated successfully.");
else
    MessageBox.Show("Printing failed.");

// Assuming 'viewer' is an instance of the Viewer class
// This will print the document silently without showing the print dialog or the print progress dialog
bool printSuccess = viewer.Print(showPrintDialog: false, showPrintProgressDialog: false);
if (printSuccess)
    MessageBox.Show("Printing initiated successfully.");
else
    MessageBox.Show("Printing failed.");

// Assuming 'viewer' is an instance of the Viewer class
// This will show both the print dialog and the print progress dialog to the user, and print on the UI thread
bool printSuccess = viewer.Print(showPrintDialog: true, showPrintProgressDialog: true, usePrintingThread: false);
if (printSuccess)
    MessageBox.Show("Printing initiated successfully.");
else
    MessageBox.Show("Printing failed.");

// Assuming 'viewer' is an instance of the Viewer class
// Configure printing to show print dialog, print progress dialog, and use a separate printing thread
viewer.Print(PrintingSettings.ShowPrintDialog | PrintingSettings.ShowPrintProgressDialog | PrintingSettings.UsePrintingThread);

