public partial class MyForm : Form
{
	private Viewer viewer;
	public MyForm()
	{
		InitializeComponent();
		viewer = new Viewer();

		// Subscribe to the Find event
		viewer.Find += Viewer_Find;

		this.Controls.Add(viewer);
		viewer.Dock = DockStyle.Fill;
	}
}
private void Viewer_Find(object sender, FindEventArgs e)
{
	if (e.Found)
		MessageBox.Show($"Text found on page {e.PageIndex + 1}.", "Search", MessageBoxButtons.OK, MessageBoxIcon.Information);
	else
		MessageBox.Show("Text not found.", "Search", MessageBoxButtons.OK, MessageBoxIcon.Information);
}

public partial class MyForm : Form
{
	private Viewer viewer;
	public MyForm()
	{
		InitializeComponent();
		// Initialize the viewer
		viewer = new Viewer();
		this.Controls.Add(viewer);
		// Subscribe to the HyperLink event
		viewer.HyperLink += Viewer_HyperLink;
	}

	private void Viewer_HyperLink(object sender, HyperLinkEventArgs e)
	{
		// Check if the hyperlink is not null or empty
		if (!string.IsNullOrEmpty(e.HyperLink))
		{
		    // Open the hyperlink in the default web browser
		    System.Diagnostics.Process.Start(e.HyperLink);
		    // Optionally, set Handled to true to prevent the default behavior
		    e.Handled = true;
		}
	}
}

